	"runtime"
)

// Медленная функция с потерей типизации и аллокацией Interface()
func SlowExtract(v reflect.Value) any {
	return v.Interface()
}

// Быстрая функция без боксинга в any
func FastExtractInt(v reflect.Value) int64 {
	return v.Int()
}

func main() {
	var val int64 = 888000
	rVal := reflect.ValueOf(&val).Elem()
	const N = 200_000

	// 1. Замер SlowExtract (Interface)
	var m1, m2 runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&m1)

	var dummyAny any
	for i := 0; i < N; i++ {
		dummyAny = SlowExtract(rVal)
	}

	runtime.ReadMemStats(&m2)
	allocsSlow := m2.Mallocs - m1.Mallocs
	bytesSlow := m2.TotalAlloc - m1.TotalAlloc

	// 2. Замер FastExtractInt (Zero-Alloc)
	runtime.GC()
	runtime.ReadMemStats(&m1)

	var dummyInt int64
	for i := 0; i < N; i++ {
		dummyInt = FastExtractInt(rVal)
	}

	runtime.ReadMemStats(&m2)
	allocsFast := m2.Mallocs - m1.Mallocs
	bytesFast := m2.TotalAlloc - m1.TotalAlloc

	_ = dummyAny
	_ = dummyInt

	fmt.Printf("1. SlowExtract (Interface): %d байт, %d аллокаций (%.1f B/op)\n",
		bytesSlow, allocsSlow, float64(bytesSlow)/N)
	fmt.Printf("2. FastExtractInt (Direct): %d байт, %d аллокаций (0.0 B/op - ИДЕАЛЬНО!)\n",
		bytesFast, allocsFast)
}

package main

import (
	"fmt"
	"reflect"
)

type FieldDesc struct {
	Name   string
	Index  int
	Offset uintptr
	Kind   reflect.Kind
}

type FastStructSchema struct {
	TypeName string
	Fields   []FieldDesc
}

func NewFastSchema(sample any) *FastStructSchema {
	t := reflect.TypeOf(sample)
	if t.Kind() == reflect.Pointer {
		t = t.Elem()
	}

	if t.Kind() != reflect.Struct {
		panic("NewFastSchema ожидает структуру")
	}

	schema := &FastStructSchema{
		TypeName: t.Name(),
		Fields:   make([]FieldDesc, t.NumField()),
	}

	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		schema.Fields[i] = FieldDesc{
			Name:   f.Name,
			Index:  i,
			Offset: f.Offset,
			Kind:   f.Type.Kind(),
		}
	}

	return schema
}

// FastIterate выполняет быстрый обход полей структуры по готовой схеме
func FastIterate(obj any, schema *FastStructSchema) {
	v := reflect.ValueOf(obj)
	if v.Kind() == reflect.Pointer {
		v = v.Elem()
	}

	fmt.Printf("Быстрый обход структуры %s (кэшированная схема):\n", schema.TypeName)
	for _, f := range schema.Fields {
		fieldVal := v.Field(f.Index)
		fmt.Printf("  • [%d] %-12s (Kind: %-8s, Offset: %2d) = %v\n",
			f.Index, f.Name, f.Kind, f.Offset, fieldVal.Interface())
	}
}

type TransactionRecord struct {
	TxID      int64
	Sender    string
	Receiver  string
	Amount    float64
	Confirmed bool
}

func main() {
	// 1. Построение схемы один раз при старте сервиса
	schema := NewFastSchema(TransactionRecord{})

	tx := TransactionRecord{
		TxID:      8849201,
		Sender:    "0xAlice",
		Receiver:  "0xBob",
		Amount:    150.75,
		Confirmed: true,
	}

	// 2. Высокоскоростная обработка объекта
	FastIterate(tx, schema)
}

