}

package main

import (
	"fmt"
	"reflect"
	"strings"
)

type AddressDetails struct {
	PostalCode string
	City       string
}

type CustomerInfo struct {
	Name    string
	Address AddressDetails
}

type BillingData struct {
	Customer CustomerInfo
	Currency string
}

type OrderMessage struct {
	ID      string
	Billing BillingData
}

// PrecomputeFieldPaths строит карту "путь.к.полю" -> []int
func PrecomputeFieldPaths(t reflect.Type) map[string][]int {
	if t.Kind() == reflect.Pointer {
		t = t.Elem()
	}

	pathMap := make(map[string][]int)

	var scan func(cur reflect.Type, currentPath string, currentIndex []int)
	scan = func(cur reflect.Type, currentPath string, currentIndex []int) {
		for i := 0; i < cur.NumField(); i++ {
			f := cur.Field(i)
			fieldName := strings.ToLower(f.Name)
			newPath := fieldName
			if currentPath != "" {
				newPath = currentPath + "." + fieldName
			}

			fullIndex := append(append([]int{}, currentIndex...), f.Index...)
			pathMap[newPath] = fullIndex

			if f.Type.Kind() == reflect.Struct {
				scan(f.Type, newPath, fullIndex)
			}
		}
	}

	scan(t, "", nil)
	return pathMap
}

func main() {
	order := OrderMessage{
		ID: "ORD-991122",
		Billing: BillingData{
			Customer: CustomerInfo{
				Name: "Иван Кузнецов",
				Address: AddressDetails{
					PostalCode: "101000",
					City:       "Москва",
				},
			},
			Currency: "RUB",
		},
	}

	// 1. Предварительный расчет путей при старте приложения
	paths := PrecomputeFieldPaths(reflect.TypeOf(order))

	fmt.Println("=== Предварительно вычисленные пути полей структуры ===")
	for path, idx := range paths {
		fmt.Printf("  • %-35s => %v\n", path, idx)
	}

	// 2. Мгновенное чтение глубоко вложенного поля в рантайме
	targetKey := "billing.customer.address.postal_code"
	idxPath := paths[targetKey]

	v := reflect.ValueOf(&order).Elem()
	postalField := v.FieldByIndex(idxPath)

	fmt.Printf("\nПрочитано поле %q: %s\n", targetKey, postalField.String())

	// 3. Мгновенная модификация глубокого поля
	postalField.SetString("190000")
	fmt.Printf("После обновления: новый индекс = %s\n",
		order.Billing.Customer.Address.PostalCode)
}

package main

import (
	"fmt"
	"reflect"
	"strconv"
	"time"
)

type UserEvent struct {
	UserID    int64
	Action    string
	Timestamp int64
}

// 1. Рефлексивный сериализатор (медленный, но универсальный)
func SerializeReflect(v any) string {
	val := reflect.ValueOf(v)
	typ := val.Type()

	var res string
	for i := 0; i < val.NumField(); i++ {
		if i > 0 {
			res += "&"
		}
		res += fmt.Sprintf("%s=%v", typ.Field(i).Name, val.Field(i).Interface())
	}
	return res
}

// 2. Сгенерированный сериализатор (быстрый, zero-alloc буфер)
func (u UserEvent) SerializeCodegen(dst []byte) []byte {
	dst = append(dst, "UserID="...)
	dst = strconv.AppendInt(dst, u.UserID, 10)
	dst = append(dst, "&Action="...)
	dst = append(dst, u.Action...)
	dst = append(dst, "&Timestamp="...)
	dst = strconv.AppendInt(dst, u.Timestamp, 10)
	return dst
}

func main() {
	event := UserEvent{
		UserID:    880011,
		Action:    "LOGIN_SUCCESS",
		Timestamp: 1718005500,
	}

	const N = 200_000

	// 1. Рефлексия
	start := time.Now()
	var dummyReflect string
	for i := 0; i < N; i++ {
		dummyReflect = SerializeReflect(event)
	}
	tReflect := time.Since(start)

	// 2. Кодогенерация
	buf := make([]byte, 0, 128)
	start = time.Now()
	for i := 0; i < N; i++ {
		buf = event.SerializeCodegen(buf[:0])
	}
	tCodegen := time.Since(start)

	fmt.Printf("Результат сериализации:\n  %s\n\n", dummyReflect)
	fmt.Printf("1. Рефлексия:    %10v (%.2f нс/оп)\n", tReflect, float64(tReflect.Nanoseconds())/N)
	fmt.Printf("2. Кодогенерация:%10v (%.2f нс/оп)\n\n", tCodegen, float64(tCodegen.Nanoseconds())/N)

	fmt.Printf("Сгенерированный код быстрее в %.1f раз!\n",
		float64(tReflect)/float64(tCodegen))
}

